    // Outer loop: iterate through each element
    for i from 0 to n-2 do:

        // Assume current position holds the minimum
        minIndex = i

        // Inner loop: find the actual minimum in remaining unsorted portion
        for j from i+1 to n-1 do:
            if A[j] < A[minIndex] then:
